<!doctype html><html><head><meta charset="utf-8"><title>Party Statement</title><style>@page{size:A4 portrait;margin:8mm}*{box-sizing:border-box}html,body{margin:0;padding:0}body{font:8px Arial;color:#182536}.et-ps-print-canvas{background:#f2f5f8;padding:16px}.et-ps-print-page{width:210mm;min-height:297mm;max-width:100%;margin:0 auto;background:#fff;padding:8mm}.et-ps-company-band,.et-ps-party-band{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;border-bottom:2px solid #182536;padding-bottom:5px;margin-bottom:6px}.et-ps-party-band{border-bottom:1px solid #182536}.et-ps-company{display:flex;gap:8px;align-items:center;min-width:0}.et-ps-company img{width:42px;height:42px;object-fit:contain}.et-ps-company strong{display:block;font-size:12px;font-weight:700}.et-ps-company small,.et-ps-party-band span{display:block;font-size:8px}.et-ps-meta,.et-ps-report-identity{text-align:right;white-space:nowrap}.et-ps-report-identity h2{font-size:12px;margin:0 0 2px}.et-ps-meta p,.et-ps-report-identity p{margin:1px 0}.et-ps-party-name{font-size:10px;font-weight:700}.et-ps-ledger-table{width:100%;max-width:100%;table-layout:fixed;border-collapse:collapse;font-size:8px;font-variant-numeric:tabular-nums}.et-ps-ledger-table th,.et-ps-ledger-table td{border:.7pt solid #000;padding:2px 3px;text-align:left;vertical-align:top;white-space:nowrap}.et-ps-ledger-table th{background:#edf3f9;print-color-adjust:exact;-webkit-print-color-adjust:exact}.et-ps-ledger-table th:nth-last-child(-n+3),.et-ps-ledger-table td:nth-last-child(-n+3){text-align:right}.et-ps-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin-top:7px;break-inside:avoid;page-break-inside:avoid}.et-ps-summary>div{border:.7pt solid #000;padding:3px}.et-ps-summary strong,.et-ps-summary span{display:block}.et-ps-caption{text-align:right;margin:4px 0 0}col:nth-child(1){width:8%}col:nth-child(2){width:4%}col:nth-child(3){width:9%}col:nth-child(4){width:11%}col:nth-child(5){width:13%}col:nth-child(6){width:26%}col:nth-child(7){width:9%}col:nth-child(8){width:9%}col:nth-child(9){width:11%}thead{display:table-header-group}tr{break-inside:avoid;page-break-inside:avoid}@media print{html,body{margin:0;padding:0;background:#fff}.et-ps-print-canvas{padding:0;background:#fff}.et-ps-print-page{width:auto;min-height:auto;max-width:none;margin:0;padding:0;border:0;box-shadow:none}}</style></head><body><div class="et-ps-print-canvas"><div class="et-ps-print-page">@include('accounting.party-statement._document-header')<table class="et-ps-ledger-table"><colgroup><col><col><col><col><col><col><col><col><col></colgroup><thead><tr><th>Date</th><th>Type</th><th>Invoice / Ref.</th><th>Passenger / Group</th><th>Service Ref.</th><th>Sector / Description</th><th>Debit</th><th>Credit</th><th>Balance</th></tr></thead><tbody>@foreach($statement['rows'] as $row)<tr><td>{{ \App\Support\PartyStatementPresentation::date($row['date']) }}</td><td>{{ \App\Support\PartyStatementPresentation::type($row['type']) }}</td><td>{{ $row['reference'] ?: '—' }}</td><td>{{ $row['party'] }}</td><td>{{ $row['service_ref'] }}</td><td>{{ $row['description'] }}</td><td>{{ $row['debit'] === null ? '' : number_format($row['debit'],2) }}</td><td>{{ $row['credit'] === null ? '' : number_format($row['credit'],2) }}</td><td>{{ number_format(abs($row['balance']),2) }} {{ $row['balance'] < 0 ? 'Cr' : 'Dr' }}</td></tr>@endforeach</tbody></table><div class="et-ps-summary"><div><strong>Opening Balance</strong><span>PKR {{ number_format(abs($statement['opening']),2) }}</span></div><div><strong>Total Debit</strong><span>PKR {{ number_format($statement['total_debit'],2) }}</span></div><div><strong>Total Credit</strong><span>PKR {{ number_format($statement['total_credit'],2) }}</span></div><div><strong>Closing Balance</strong><span>PKR {{ number_format(abs($statement['closing']),2) }} {{ $statement['closing_side'] }}</span></div></div><p class="et-ps-caption">Closing Balance Nature: {{ $statement['caption'] }}</p></div></div></body></html>
